package com.aistock.scheduler.security;
import com.aistock.common.*;import com.aistock.scheduler.admin.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;import java.util.*;import java.time.Instant;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminTaskAccessTest {
 SessionIdentityClient identity;AdminTaskService service;MockMvc mvc;
 @BeforeEach void setup(){identity=mock(SessionIdentityClient.class);service=mock(AdminTaskService.class);when(service.list(any(),any())).thenReturn(new AdminTaskRecords.Page<>(List.of(),null,false,Instant.now()));mvc=build("private-server-token");}
 MockMvc build(String token){var mapper=new ObjectMapper().findAndRegisterModules();return MockMvcBuilders.standaloneSetup(new AdminTaskController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminTaskAccessFilter(identity,token,mapper)).build();}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder list(){return get("/api/v1/admin/tasks").param("createdFrom","2026-10-01").param("createdTo","2026-10-20");}
 void role(String role){when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(UUID.randomUUID(),role,false,1),"trace"));}
 @Test void anonymousOrForgedIdentityNeverQueries()throws Exception{mvc.perform(list().header("X-Role","ADMIN").header("X-Service-Token","forged")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("AUTH_REQUIRED"));verifyNoInteractions(service,identity);}
 @Test void userForbiddenBeforeMalformedQuery()throws Exception{role("USER");mvc.perform(get("/api/v1/admin/tasks").cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void administratorAllowedAndSessionResolvedEachRequest()throws Exception{role("ADMIN");mvc.perform(list().cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));when(identity.resolve(any(),anyString())).thenReturn(new ApiResponse<SessionIdentityClient.Identity>("AUTH_REQUIRED","请登录",null,"trace"));mvc.perform(list().cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isUnauthorized());verify(service,times(1)).list(any(),any());verify(identity,times(2)).resolve(any(),eq("private-server-token"));}
 @Test void unavailableMalformedOrUnknownIdentityFailsClosed()throws Exception{for(var who:Arrays.asList(null,new SessionIdentityClient.Identity(null,"ADMIN",false,1),new SessionIdentityClient.Identity(UUID.randomUUID(),"OWNER",false,1))){reset(identity,service);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(who,"trace"));mvc.perform(list().cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("USER_SERVICE_UNAVAILABLE"));verifyNoInteractions(service);}when(identity.resolve(any(),anyString())).thenThrow(new IllegalStateException("private secret"));mvc.perform(list().cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isServiceUnavailable()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private secret"))));}
 @Test void blankServiceCredentialAndDuplicateCookiesRejected()throws Exception{role("ADMIN");build("").perform(list().cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isServiceUnavailable());for(String duplicate:List.of("session","other"))mvc.perform(list().cookie(new Cookie("AISTOCK_SESSION","session"),new Cookie("AISTOCK_SESSION",duplicate))).andExpect(status().isUnauthorized());verifyNoInteractions(service,identity);}
 @Test void writesAndHeadNeverReachQuery()throws Exception{role("ADMIN");mvc.perform(post("/api/v1/admin/tasks").cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isNotFound());mvc.perform(head("/api/v1/admin/tasks").cookie(new Cookie("AISTOCK_SESSION","session"))).andExpect(status().isNotFound());verifyNoInteractions(service);}
 @Test void corsPreflightIsBoundedAndReadsNoIdentityOrTask()throws Exception{var mapper=new ObjectMapper().findAndRegisterModules();var config=new AdminTaskSecurityConfiguration();var cors=config.adminTaskCors("http://127.0.0.1:15173").getFilter();var local=MockMvcBuilders.standaloneSetup(new AdminTaskController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(cors,new AdminTaskAccessFilter(identity,"server-token",mapper)).build();local.perform(options("/api/v1/admin/tasks").header("Origin","http://127.0.0.1:15173").header("Access-Control-Request-Method","GET")).andExpect(status().isOk()).andExpect(header().string("Access-Control-Allow-Credentials","true")).andExpect(header().string("Cache-Control","no-store"));local.perform(options("/api/v1/admin/tasks").header("Origin","https://untrusted.example").header("Access-Control-Request-Method","GET")).andExpect(status().isForbidden());local.perform(get("/api/v1/admin/tasks").header("Origin","https://untrusted.example")).andExpect(status().isForbidden());verifyNoInteractions(identity,service);}
 @Test void sessionInputToStringRedacted(){org.junit.jupiter.api.Assertions.assertFalse(new SessionIdentityClient.ResolveInput("private-session").toString().contains("private-session"));}
}
